mapper.select:
SELECT l.id FROM ocean_gis.gis_vector_layer l JOIN ocean_gis.gis_data_set d ON d.id=l.data_set_id AND d.deleted=0
LEFT JOIN ocean_gis.gis_vector_generalization c ON c.layer_id=l.id
WHERE l.deleted=0 AND l.layer_status='READY' AND c.layer_id IS NULL ORDER BY l.id LIMIT #{limit}

mapper.update:
UPDATE ocean_gis.gis_vector_generalization_build SET build_status=#{status},lease_expires_at=NULL,
    finish_time=CURRENT_TIMESTAMP,max_tile_bytes=#{maxBytes},error_message=#{error}
WHERE id=#{id} AND attempt=#{attempt} AND build_status='RUNNING'

mapper.select:
SELECT f.id,f.properties::text AS properties_json,f.version
FROM ocean_gis.gis_vector_generalized_member m JOIN ocean_gis.gis_vector_feature f ON f.id=m.feature_id
WHERE m.build_id=#{buildId} AND m.zoom=#{z} AND m.representation_id=#{representationId}
  AND f.layer_id=#{layerId} AND f.deleted=0 AND f.id>#{afterId}
ORDER BY f.id LIMIT #{limit}
